/*
 * A381101  Allouche-Johnson binary sequence based on the Narayana's cows
 *          sequence A000930.
 * https://oeis.org/A381101
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth element of the infinite word generated by the
 *            Allouche–Johnson morphism a→ab, b→c, c→d, d→de, e→f, f→a,
 *            followed by the letter map {a,e,f→0, b,c,d→1}. Equivalently, let
 *            X(0)=X(1)=X(2)=0 and for k ≥ 3 X(k)=X(k-1) complement(X(k-3)).
 *            The required term is the n‑th bit of the limit of...
 * Range:     u8 n <= 129, u16 n <= 129, u32 n <= 129, u64 n <= 129,
 *            u128 n <= 129, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>

/*  Cache of lengths |X(k)| = Narayana's cows numbers.  */
#define MAX_LEN_CACHE 200          /* enough for n up to at least 10 000 */
static idx_t _len_cache[MAX_LEN_CACHE];
static idx_t _len_cache_size = 0;  /* number of computed entries */

/*  Return |X(k)|, computing the cache if necessary.  */
static idx_t _len_of(idx_t k)
{
    if (k < 3) return (idx_t)1;          /* X(0), X(1), X(2) are single bits */

    if (k < _len_cache_size) return _len_cache[k];

    /* extend cache up to k */
    for (idx_t i = _len_cache_size; i <= k; ++i) {
        if (i < 3)                       /* safety, though already handled */
            _len_cache[i] = (idx_t)1;
        else
            _len_cache[i] = _len_cache[i-1] + _len_cache[i-3];
    }
    _len_cache_size = k + 1;
    return _len_cache[k];
}

/*  Recursive helper that returns the bit at position 'pos' of X(idx).
    The bit is 0 or 1.  */
static seq_t _get_bit_rec(idx_t idx, idx_t pos)
{
    if (idx <= 2)            /* X(0), X(1), X(2) are the single zero bit */
        return (seq_t)0;

    idx_t len_prev = _len_of(idx - 1);
    if (pos < len_prev)
        return _get_bit_rec(idx - 1, pos);
    else {
        idx_t pos2 = pos - len_prev;               /* position in complement(X(idx-3)) */
        seq_t b   = _get_bit_rec(idx - 3, pos2);
        return (seq_t)(b ^ 1);                     /* complement */
    }
}

/*  Public function required by the exercise.  */
seq_t a(idx_t n)
{
    /* find smallest idx such that |X(idx)| > n */
    idx_t idx = 0;
    while (_len_of(idx) <= n)
        ++idx;

    return _get_bit_rec(idx, n);
}
